/**
 * `agent/sandbox/workspace/**`: files seeded into each local session workspace.
 */
import { join, relative } from "node:path";
import { displayPath } from "./context.js";
import { isDirectory, isFile, toPosix, walkFiles } from "./fs.js";
export async function loadSeedFiles(ctx, agentDir) {
    const sandboxDir = join(agentDir, "sandbox");
    for (const candidate of ["sandbox.ts", join("sandbox", "sandbox.ts")]) {
        if (await isFile(join(agentDir, candidate))) {
            ctx.diagnostics.push({
                severity: "warning",
                path: displayPath(ctx, join(agentDir, candidate)),
                message: "Custom sandbox backends are not supported; the agent runs in the session workspace directory. Ignoring.",
            });
        }
    }
    const workspaceDir = join(sandboxDir, "workspace");
    if (!(await isDirectory(workspaceDir))) {
        return [];
    }
    const seedFiles = [];
    for (const filePath of await walkFiles(workspaceDir)) {
        seedFiles.push({
            relativePath: toPosix(relative(workspaceDir, filePath)),
            sourcePath: filePath,
        });
    }
    return seedFiles;
}
